#!/usr/bin/env bash
# Pull the LiveKit URL/key/secret generated by deploy/livekit-linode.sh into this repo's .env, the
# Worker's secrets, and the GitHub repository secrets. Values are moved by file and pipe; nothing is
# printed. Run from the repo root on the machine that holds ~/.ssh/trackaa_origin.
set -euo pipefail
BOX="${BOX:-root@50.116.30.232}"
KEY="${KEY:-$HOME/.ssh/trackaa_origin}"
REPO="${REPO:-greg-m-k/summonersgame}"
TMP="$(mktemp)"
trap 'rm -f "$TMP"' EXIT

ssh -i "$KEY" -o BatchMode=yes "$BOX" 'cat /etc/livekit/keys.env' > "$TMP"
grep -q '^LIVEKIT_API_SECRET=' "$TMP" || { echo "no keys on the box yet; run deploy/livekit-linode.sh first" >&2; exit 1; }

# .env: replace the three lines in place (append any that are missing)
for name in LIVEKIT_URL LIVEKIT_API_KEY LIVEKIT_API_SECRET; do
  value="$(grep "^${name}=" "$TMP" | cut -d= -f2-)"
  if grep -q "^${name}=" .env; then
    awk -v n="$name" -v v="$value" 'BEGIN{FS=OFS="="} $1==n {print n "=" v; next} {print}' .env > .env.next && mv .env.next .env
  else
    printf '%s=%s\n' "$name" "$value" >> .env
  fi
  printf '%s' "$value" | gh secret set "$name" --repo "$REPO" >/dev/null
  echo "github secret $name set"
done

node scripts/secrets-json.mjs | npx wrangler secret bulk >/dev/null && echo "worker secrets updated"
echo "LIVEKIT_URL is now $(grep '^LIVEKIT_URL=' .env | cut -d= -f2-)"
